{
  "name": "opencode-usage",
  "version": "0.1.0",
  "private": true,
  "repository": "github:mdc-git/opencode-usage",
  "type": "module",
  "exports": {
    ".": "./plugins/usage/index.ts",
    "./rpc": "./plugins/usage/rpc.ts",
    "./tui": "./plugins/usage/tui.tsx"
  },
  "sideEffects": false,
  "engines": {
    "node": ">=22"
  },
  "scripts": {
    "check": "bun run prettier --check --config tooling/prettier.json . && bun run eslint --config tooling/eslint.config.js . && bun run tsc --project tooling/tsconfig.json --noEmit",
    "fix": "bun run prettier --write --config tooling/prettier.json . && bun run eslint --config tooling/eslint.config.js . --fix && bun run check"
  },
  "files": [
    "plugins"
  ],
  "dependencies": {
    "@opencode/plugin": "^2.2.5",
    "zod": "^4.6.6"
  },
  "devDependencies": {
    "@opentui/core": "^0.6.0",
    "@opentui/solid": "^0.6.0",
    "@tsconfig/bun": "^1.0.11",
    "@types/bun": "^1.4.2",
    "eslint": "^10.12.0",
    "eslint-config-prettier": "^10.1.8",
    "eslint-config-xo": "^5.0.0",
    "prettier": "^3.9.10",
    "solid-js": "^1.9.17",
    "typescript": "^6.0.3"
  },
  "peerDependencies": {
    "@opentui/core": ">=0.5.12",
    "@opentui/solid": ">=0.5.12",
    "solid-js": ">=1.9.0"
  },
  "$schema": "https://json.schemastore.org/package.json"
}
